  26     /**
  27      * Post-processes AI output to remove common conversational prefixes from small models.
  28      */
  29     private cleanAiOutput(text: string): string {
  30         if (!text) return text;
  31         
  32         // List of common conversational prefixes used by small models like Gemma/Phi
  33         const patterns = [
  34             /^Sure,? (here is|here's) the [^:]+:?\s*/i,
  35             /^Sure,? here (is|'s) [^:]+:?\s*/i,
  36             /^Certainly!? [^:]+:?\s*/i,
  37             /^As requested,? [^:]+:?\s*/i,
  38             /^I have [^:]+ below:?\s*/i,
  39             /^The following is [^:]+:?\s*/i,
  40             /^Ok,? (here is|here's) [^:]+:?\s*/i,
  41             /^Below is the [^:]+:?\s*/i,
  42             /^Sure,? I can [^:]+:?\s*/i,
  43         ];
  44 
  45         let cleaned = text.trim();
  46         // Run multiple passes to catch nested filler
  47         for (let i = 0; i < 2; i++) {
  48             for (const pattern of patterns) {
  49                 cleaned = cleaned.replace(pattern, '');
  50             }
  51             cleaned = cleaned.trim();
  52         }
  53         return cleaned;
  54     }
  55 
  56     async runFlow<TInput, TOutput>(flow: any, input: TInput, flowName?: string): Promise<Result<TOutput, AiError>> {
  57         try {
  58             let result: any;
  59             if (!flowName) {
  60                 result = await flow(input);
  61             } else {
  62                 const model = selectModel({ flowName });
  63                 result = await executeWithQueue(
  64                     generateRequestId(),
  65                     model,
  66                     flowName,
  67                     () => flow(input)
  68                 );
  69             }
  70 
  71             // Post-process string outputs to remove conversational filler
  72             if (result && typeof result === 'object') {
  73                 for (const key in result) {
  74                     if (typeof result[key] === 'string') {
  75                         result[key] = this.cleanAiOutput(result[key]);
  76                     }
  77                 }
  78             } else if (typeof result === 'string') {
  79                 result = this.cleanAiOutput(result);
  80             }
  81 
  82             return Result.ok(result as TOutput);
  83         } catch (error: any) {
  84             console.warn(`Queue or flow execution failed for ${flowName || 'unnamed flow'}`, error);
  85             try {
  86                 const result = await flow(input);
  87                 return Result.ok(result);
  88             } catch (fallbackError: any) {
  89                 return Result.fail(AiError.generationFailed(fallbackError.message));
  90             }
  91         }
