  11 /**
  12  * Returns a prompt instruction string for JSON output.
  13  * @param jsonExample - A plain JSON example string showing the expected output shape.
  14  */
  15 export function getJsonPromptInstructions(jsonExample: string): string {
  16     return `Your response MUST be a valid JSON object. Do not include any text outside the JSON block.
  17 Expected JSON shape:
  18 \`\`\`json
  19 ${jsonExample}
  20 \`\`\``;
  21 }
  22 
  23 export interface ValidateJsonOutputOptions<T> {
  24     schema: z.ZodType<T>;
  25     output: unknown;
  26     flowName?: string;
  27     attemptRecovery?: boolean;
  28     enableLogging?: boolean;
  29     fallbackFn?: (rawOutput: unknown) => T | null;
  30 }
  31 
  32 export interface ValidateJsonOutputResult<T> {
  33     success: boolean;
  34     data?: T;
  35     error?: string;
  36 }
  37 
  38 /**
  39  * Validates and parses AI output against a Zod schema.
  40  */
  41 export function validateJsonOutput<T>(options: ValidateJsonOutputOptions<T>): ValidateJsonOutputResult<T> {
  42     const { schema, output, flowName = 'unknown', attemptRecovery = false, enableLogging = false, fallbackFn } = options;
  43 
  44     // If output is already a valid object, try parsing directly
  45     const parsed = schema.safeParse(output);
  46     if (parsed.success) {
  47         return { success: true, data: parsed.data };
  48     }
  49 
  50     if (enableLogging) {
  51         console.warn(`[${flowName}] Schema validation failed:`, parsed.error.message);
  52     }
  53 
  54     // Attempt recovery by extracting JSON from a string
  55     if (attemptRecovery && typeof output === 'string') {
  56         try {
  57             const jsonMatch = output.match(/```json\n?([\s\S]*?)\n?```/) || output.match(/({[\s\S]*})/);
  58             if (jsonMatch) {
  59                 const extracted = JSON.parse(jsonMatch[1] || jsonMatch[0]);
